#  Academic Radiology: ≤5,000단어, 참고 ≤50, 표 ≤5, 그림 ≤10, 구조 초록 250(Rationale and Objectives·Materials and Methods·Results·Conclusion), Take-Home Messages 1–2(각 ≤50단어), 키워드 3–5, 짧은 제목 ≤6단어, 이중 익명.
from numbers_ches import load, ROB, BL, PA, FAC, UPT, HYP
N = load()
def ci(v, src=None):
    r = (src or N["main"])[v]; return f"RR {r['IRR']:.3f}; 95% CrI {r['lo']:.3f}–{r['hi']:.3f}"
def tci(t): return f"RR {t[0]:.3f}; 95% CrI {t[1]:.3f}–{t[2]:.3f}"
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["nco"][(o, v)]
SC = lambda s, v: N["sens_main"][s][v]
WI = lambda v, w: N["win_irr"][(v, w)]
PH = lambda s, v: N["ph_extra"][(s, v)]
EN = {"전라남도": "South Jeolla", "경상북도": "North Gyeongsang", "경상남도": "South Gyeongsang", "충청남도": "South Chungcheong", "전라북도": "North Jeolla",
      "강원도": "Gangwon", "부산시": "Busan", "충청북도": "North Chungcheong", "대구시": "Daegu", "경기도": "Gyeonggi", "서울시": "Seoul", "인천시": "Incheon",
      "광주시": "Gwangju", "울산시": "Ulsan", "대전시": "Daejeon", "세종시": "Sejong", "제주도": "Jeju"}
def sidos(d, n):
    l = [f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n]]; return ", ".join(l[:-1]) + " and " + l[-1]
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
TITLE = "Where is a screening chest radiograph called abnormal? District variation in other chest disease flags over 14 years of Korean national health screening"
RUNNING = "District variation in chest radiograph flags"
assert ":" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower() and len(RUNNING.split()) <= 6
KEYWORDS = ["Mass screening", "Radiography, thoracic", "Observer variation", "Spatio-temporal analysis", "Republic of Korea"]
assert 3 <= len(KEYWORDS) <= 5
NHYP = N["n_hyp"]; assert NHYP == 11
SUP = {"methods": 1, "covariates": 2, "checks": 3, "maps": 4, "windows": 5, "specs": 6, "posthoc": 7, "strobe": 8}
def sup(k): return f"Supplementary Appendix S{SUP[k]}"
_pc = lambda v: f"{100*N['mv'][v]['cred_frac']:.0f}%"
ALT = N["retention"]; D = N["desc"]
BEST = min(KH, key=lambda a: N["s43_waic"][a]); assert BEST == "KH_typeI"
nat = N["nat_pos_y"]; NR = N["rate"]; VP = {k: v["share_of_linear_predictor_var"] for k, v in N["varpart"].items()}
NULL_EXPO = ["ext__tb_history_share", "current_smoking_rate", "factory_land_share", "coal_plant_host"]
NULL_OTHER = [UPT, "ext__clinics_per100k", "walking_practice_rate"]

TAKE_HOME = [
 f"Across {N['n_districts']} Korean districts and {N['exam_total']/1e6:.0f} million screening examinations, the sex- and age-standardised share of chest radiographs flagged as other chest disease differed more than two-fold between districts and kept a stable, spatially structured pattern for 14 years.",
 "Tuberculosis history, smoking, industrial land, coal-fired power plants and former coal-mining areas did not account for this geography, which points to regional differences in how screening radiographs are read and reported as a target for audit.",
]
assert len(TAKE_HOME) == 2 and all(len(t.split()) <= 50 for t in TAKE_HOME)

ABSTRACT = {
 "Rationale and Objectives": "Chest radiography is part of Korea's national general health screening, and the share of radiographs flagged as other chest disease is published for every district. This study described the geography of this flag and tested whether district exposures that cause chest radiograph abnormalities explain it.",
 "Materials and Methods": f"Ecological panel study of {N['exam_total']/1e6:.0f} million screening examinations in {N['n_districts']} districts, 2011–2024. Expected numbers were standardised for sex and age. Negative binomial Bayesian spatiotemporal models related standardised ratios to {NHYP} district characteristics (tuberculosis history among attendees, smoking, industrial land, coal-fired power plants, deprivation, screening uptake, clinic density and physical activity), with 200 covariate subsets, space–time interaction models and negative-control exposures.",
 "Results": f"Of all examinations, {N['cases_total']/1e6:.1f} million ({100*N['cases_total']/N['exam_total']:.1f}%) were flagged. Standardised ratios ranged from {D['sir_min']:.2f} to {D['sir_max']:.2f} (10th–90th percentile {D['sir_p10']:.2f}–{D['sir_p90']:.2f}), were spatially clustered (Moran's I {N['moran_year_min']:.2f}–{N['moran_year_max']:.2f} each year) and kept their district ranking (Kendall's W {N['kendall_W']:.2f}). Tuberculosis history, smoking, industrial land and coal-fired power plants were not associated. Basic livelihood security receipt was inversely associated (rate ratio per standard deviation {M[BL]['IRR']:.2f}; 95% credible interval {M[BL]['lo']:.2f}–{M[BL]['hi']:.2f}) within districts over time, not between districts. Inverse-direction associations with physical activity disappeared in two space–time interaction models.",
 "Conclusion": "Flags for other chest disease at Korean health screening vary widely and persistently between districts without tracking exposures that cause chest radiograph abnormalities. Reading and reporting practices deserve audit before the flag is used to target follow-up or to compare areas.",
}

INTRO = [
 f"Chest radiographs taken for screening often show findings that are not suspicious for cancer: in a large screening trial, such abnormalities were reported on about a third of examinations, most often granulomas, scarring or fibrosis, cardiac abnormalities and pleural fibrosis [@pinsky2006abnormalities]. In asymptomatic adults, routine chest radiography has a low yield of important disease [@tigges2004routine; @eisenberg2010low]. Whether a nonspecific finding is reported also depends on the reader; in screening radiographs, readers differed widely in how often they reported nodules, with only fair agreement [@singh2012reader].",
 f"Korea's National Health Insurance Service offers a general health examination that includes a chest radiograph to adults [@seong2017cohort]. The programme classifies each radiograph as normal, suspected pulmonary tuberculosis or suspected other chest disease, and the national statistics portal publishes the number of examinees flagged in each category for every district and year [@web:kosis2026screening]. The volume is large: health screening centres in Korea read thousands of radiographs with a low prevalence of clinically significant lesions, which has motivated work on artificial intelligence (AI) triage of normal radiographs [@yoo2022artificial; @kim2021performance; @kim2023multicentre]. In Korea's national lung cancer screening programme with low-dose computed tomography, positive rates varied widely between radiologists and institutions [@hwang2021variability]; how far the much larger chest radiograph screening programme varies between areas is not known.",
 f"Several district exposures could plausibly raise the rate of abnormal chest radiographs. Healed tuberculosis leaves radiologic changes associated with airflow obstruction in Korean adults [@hwang2014association; @choi2017definition; @park2023airflow], and tuberculosis notification in Korea remains concentrated in older adults [@lee2025tuberculosis]. Smoking, occupational dust and fumes [@murgia2022occupational; @torn2017occupational; @lam2012past; @grahn2021occupational], pneumoconiosis among former dust-exposed workers [@lee2011development; @chong2006pneumoconiosis] and air pollution, including that near coal-fired power plants [@hii2022respiratory; @komisarow2021effect; @lee2025assessing], are associated with chronic lung disease, and interstitial lung abnormalities are common at screening [@grantorser2023prevalence; @chae2023interstitial; @jin2024interstitial]. Neighbourhood deprivation is associated with lung function decline and emphysema [@thatipelli2022neighborhood], whereas regular physical activity is associated with slower lung function decline in smokers [@garciaaymerich2007regular]. If the district geography of the flag follows these exposures, it may describe disease; if not, it may partly describe how radiographs are read and reported.",
 f"This study used 14 years of national screening statistics to describe where in Korea chest radiographs are flagged as other chest disease more often than expected for the sex and age of examinees, how stable that geography is, and whether district exposures that cause chest radiograph abnormalities, deprivation, screening selection, clinic density and physical activity are associated with it.",
]

METHODS = [
("Design, outcome and population",
 f"This ecological panel study used annual district statistics of the general health examination of the National Health Insurance Service [@seong2017cohort]. For each district and year, the number of examinees with a recorded judgement and the number flagged as suspected other chest disease on the chest radiograph were taken by sex from the national statistics portal, as were national numbers by sex and age group [@web:kosis2026screening]. This category is separate from suspected pulmonary tuberculosis; the statistics do not give the radiologic finding, the reader or the facility. Districts were harmonised to 2024 boundaries. Sejong, published only as a province row, was linked as a single district, giving {N['n_districts']} districts and {N['n_rows']:,} district-years for 2011–2024 with no missing outcome; district sums equalled national totals in every year ({sup('methods')})."),
("Sex and age standardisation",
 "Expected numbers were obtained by indirect standardisation [@inskip1983methods]. National positivity in each year, sex and age group (19 years or younger, 5-year groups from 20–24 to 80–84 years, and 85 years or older) was applied to the estimated age structure of each district's examinees, derived from the resident population by sex and 5-year age group [@web:mois2026population] and national uptake by sex and age, and rescaled to the observed number of examinees of each sex. The standardised ratio is the observed over the expected number. Using national positivity of the same year accounts for nationwide changes in positivity but not for changes that differ between districts."),
("District characteristics",
 "Characteristics and expected directions were fixed before any covariate model was fitted. Chest exposures: the share of examinees reporting treatment for pulmonary tuberculosis in the screening questionnaire, as a marker of tuberculosis history independent of the radiograph reading (+) [@hwang2014association; @choi2017definition]; current smoking from the Community Health Survey [@kang2015korea] (+); the share of district area registered as factory sites, as a marker of occupational dust and fumes (+) [@murgia2022occupational]; and the presence of a coal-fired power plant in operation during the study period (+) [@hii2022respiratory]. Deprivation: basic livelihood security receipt (+) [@thatipelli2022neighborhood] and tertiary education (−). Screening selection and reading: screening uptake (−, with healthier people attending where uptake is high [@froom1999healthy]) and clinics per 100,000 population (no direction fixed, as a marker of the share of examinations read in small clinics). Physical activity: walking, moderate-or-vigorous physical activity (−) [@garciaaymerich2007regular] and public sports facilities per 100,000 population (−). Five controls were forced into every model: urban population share, physicians per 1,000 population, sex ratio, fiscal autonomy and the share aged 80 years or older. Covariates were standardised to 1 standard deviation (SD); gaps were filled within districts (" + sup("covariates") + "; checks in " + sup("checks") + ")."),
("Statistical analysis",
 f"The likelihood was chosen by the lower widely applicable information criterion (WAIC) of the forced-controls model. Models had an offset of log expected numbers, a Besag–York–Mollié 2 (BYM2) district effect with penalised-complexity priors [@riebler2016intuitive; @simpson2017penalising], and random-walk and independent year effects, and were fitted by integrated nested Laplace approximation [@rue2009approximate] in R 4.6.0 [@web:rcore2026]. Rate ratios (RRs) per 1 SD are reported with 95% credible intervals (CrIs); an association was credible when the interval excluded 1. RRs are mutually adjusted ecological associations, not individual or causal effects [@morgenstern1995ecologic; @greenland1989ecological]. Following the multiverse approach [@steegen2016increasing], the model was refitted with 200 random covariate subsets; a covariate was subset-stable if credible in at least 75% of the subsets containing it, with the same sign in at least 95%. Residual hot and cold spots had a posterior probability above 0.95 or below 0.05 that the district RR exceeded 1, for the whole period and for 2011–2015, 2016–2019 and 2020–2024. The share of linear-predictor variance due to each model component and the share of district variance in log standardised ratios between provinces were computed."),
("Sensitivity and post hoc analyses",
 f"Knorr-Held type I–IV space–time interactions were added [@knorrheld2000bayesian]; covariates were split into district means and within-district deviations [@bell2015explaining]; the model was refitted in each window; and expected numbers were recomputed from the resident population. Further specifications varied the likelihood, priors, neighbourhoods, controls, lags, left-out provinces or years, filled values and province-by-year random effects ({sup('specs')}). Respiratory and gastric cancer deaths served as comparison outcomes and hit-and-run accidents, fires and household waste recycling as negative-control exposures [@lipsitch2010negative]; E-values were computed [@vanderweele2017sensitivity]. After the results were seen, three characteristics fixed in advance for sensitivity analysis only were added singly and together: the share of examinees flagged as suspected pulmonary tuberculosis, a second judgement from the same radiograph reading and so a marker of local reading thresholds; the share of households in detached houses; and internal medicine specialists per 100,000. The standardised ratios of seven districts with former major coal mines were compared with those of other districts ({sup('posthoc')})."),
("Ethics and reporting",
 "The study used only published aggregate statistics and involved no individual data. The Institutional Review Board of [blinded] approved the study on 4 November 2025 ([blinded]) and its continuing review on 3 November 2026 ([blinded]) and waived informed consent, and the study was conducted in accordance with the Declaration of Helsinki. Reporting follows the STROBE statement [@vonelm2007strengthening] (" + sup("strobe") + ")."),
]

_e = lambda k: tuple(N['negctl'][k][x] for x in ('IRR', 'lo', 'hi'))
RESULTS = [
("Screening and positivity",
 f"Over 2011–2024, {N['exam_total']/1e6:.1f} million examinations included {N['cases_total']:,} flagged as suspected other chest disease ({100*N['cases_total']/N['exam_total']:.2f}%; Table 1). National positivity was {nat[2011]:.2f}% in 2011, {nat[2019]:.2f}% in 2019, {min(nat.values()):.2f}% in 2021 and {nat[2024]:.2f}% in 2024. Positivity rose steeply with age, from {NR[(2024, '남자', '20-24')]:.1f}% in men and {NR[(2024, '여자', '20-24')]:.1f}% in women aged 20–24 years to {NR[(2024, '남자', '85+')]:.1f}% and {NR[(2024, '여자', '85+')]:.1f}% at 85 years or older in 2024 (Fig. 1)."),
("Spatial pattern",
 f"District standardised ratios over the whole period ranged from {D['sir_min']:.2f} to {D['sir_max']:.2f}, with a 10th–90th percentile range of {D['sir_p10']:.2f}–{D['sir_p90']:.2f}. Moran's I was {N['moran_year_min']:.2f}–{N['moran_year_max']:.2f} annually; the BYM2 spatial fraction was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f}–{N['phi'][2]:.2f}), and the structured spatial effect accounted for {100*VP['spatial_structured']:.0f}% of linear-predictor variance, the unstructured district effect {100*VP['spatial_unstructured']:.0f}%, covariates {100*(VP['fixed_hypothesis']+VP['fixed_forced_controls']):.0f}% and year effects {100*VP['year_effects']:.0f}%. Residual district RRs ranged from {N['rr_min']:.2f} to {N['rr_max']:.2f}, with {N['n_hot']} hot spots, mainly in {sidos(N['hot_by_sido'], 3)}, and {N['n_cold']} cold spots, mainly in {sidos(N['cold_by_sido'], 3)} (Fig. 2A). In all three windows, {N['hot_all_windows']} districts were hot spots and {N['cold_all_windows']} cold spots (Fig. 2B). District rankings were stable (Kendall's W {N['kendall_W']:.2f}; median Spearman's ρ between adjacent years {D['rho_year_adjacent_median']:.2f}), although ρ between 2011 and 2024 was {D['rho_2011_2024']:.2f}. Provinces accounted for {100*D['share_var_between_sido']:.0f}% of the district variance in log standardised ratios ({sup('maps')})."),
("District characteristics",
 f"The negative binomial likelihood was selected (WAIC {N['waic_nb']:,.1f} vs {N['waic_pois']:,.1f}). Adding the {NHYP} characteristics changed WAIC from {N['waic_forced']:,.1f} to {N['waic_main']:,.1f}; residual Moran's I was {N['moran_resid']:.2f}. Tuberculosis history among examinees ({ci('ext__tb_history_share')}), smoking ({ci('current_smoking_rate')}), industrial land ({ci('factory_land_share')}) and coal-fired power plants ({ci('coal_plant_host')}) were not associated, nor were screening uptake, clinic density or walking (Table 2; Fig. 3). Four characteristics were credible and three were subset-stable. Standardised ratios were lower with more basic livelihood security receipt ({ci(BL)}; subset-stable in {_pc(BL)} of subsets) and with more tertiary education ({ci('tertiary_educated_share')}; {_pc('tertiary_educated_share')}), and higher with more moderate-or-vigorous physical activity ({ci(PA)}; {_pc(PA)}) and more public sports facilities ({ci(FAC)}; {_pc(FAC)}). Apart from tertiary education, these associations ran against the expected direction. Of the negative-control exposures, fires were associated ({tci(_e('fires_per_10000'))}), whereas hit-and-run accidents and recycling were not."),
("Space–time models and sensitivity analyses",
 f"All four interaction types fitted better than the principal model (ΔWAIC {dW('KH_typeIII'):,.0f} to {dW('KH_typeI'):,.0f}; type I best). Basic livelihood security receipt remained credible in all four types (type II {tci(S43('KH_typeII', BL))}; type IV {tci(S43('KH_typeIV', BL))}). Physical activity and sports facilities remained credible in type I but not in types II or IV (type II {tci(S43('KH_typeII', PA))} and {tci(S43('KH_typeII', FAC))}); smoking became inversely associated in types II–IV (type II {tci(S43('KH_typeII', 'current_smoking_rate'))}) (Table 2). Across {ALT[BL]['n_specs']} alternative fits, basic livelihood security receipt was credible in {ALT[BL]['kept']}, physical activity in {ALT[PA]['kept']} and sports facilities in {ALT[FAC]['kept']} ({sup('specs')}). Adding province-by-year random effects lowered WAIC by {N['waic_main'] - N['s41_waic']['C4_sido_year_iid']:,.0f}. Between districts, none of the three was associated; within districts over time, basic livelihood security receipt ({tci(N['bw'][BL + '__within'])}) and physical activity ({tci(N['bw'][PA + '__within'])}) were associated. In window-specific models, basic livelihood security receipt was not credible in 2011–2015 ({tci(WI(BL, 'W1_2011-15'))}) but was in 2016–2019 and 2020–2024 ({tci(WI(BL, 'W3_2020-24'))}) ({sup('windows')}). With expected numbers from the resident population, basic livelihood security receipt remained associated ({tci(N['epop'][BL])}). For respiratory and gastric cancer deaths, basic livelihood security receipt and physical activity were not credible. E-values were {N['evalue'][BL]['E_point']:.2f} for basic livelihood security receipt, {N['evalue'][PA]['E_point']:.2f} for physical activity and {N['evalue'][FAC]['E_point']:.2f} for sports facilities. Posterior predictive 95% intervals covered {100*N['ppc']['coverage95']:.1f}% of observations, and the 2024 conditional check covered {100*N['oos']['coverage95']:.1f}% ({sup('specs')})."),
("Post hoc analyses",
 f"The share flagged as suspected pulmonary tuberculosis was not associated ({tci(PH('tb_suspect', 'ext__tb_suspect_share'))}), nor were detached-house households ({tci(PH('detached', 'detached_house_households'))}) or internal medicine specialists ({tci(PH('im_spec', 'im_specialists_per_100k'))}); with all three added, basic livelihood security receipt remained associated ({tci(PH('all3', BL))}). Unadjusted rank correlations of district standardised ratios were {D['rho_sir_tbsuspect']:.2f} with the suspected tuberculosis share and {D['rho_sir_tbhistory']:.2f} with tuberculosis history. The highest residual RR was in Taebaek ({N['rr_top'][0][1]:.2f}), a former coal-mining city, but the median RR of the seven former coal-mining districts was {N['coal_mines_med']:.2f}, against {N['coal_others_med']:.2f} elsewhere, and three of them were cold spots ({sup('posthoc')})."),
]

DISCUSSION = [
 "After standardisation for sex and age, the share of screening chest radiographs flagged as other chest disease differed more than two-fold between Korean districts and kept a stable, spatially structured pattern over 14 years. The district exposures that cause chest radiograph abnormalities, namely tuberculosis history, smoking, industrial land and coal-fired power plants, did not account for it, and former coal-mining areas were not consistently high. The remaining associations were small, arose within districts over time or depended on the space–time model.",
 "### A geography that does not follow exposure",
 "If the flag mainly reflected disease, districts with more examinees reporting tuberculosis treatment, more smokers or more industrial dust would be expected to have more flags, because healed tuberculosis leaves radiographic changes [@hwang2014association; @park2023airflow] and smoking and occupational exposures cause chronic lung disease [@murgia2022occupational; @torn2017occupational]. None of these was associated, and smoking was inversely associated in the space–time models. District averages may be too coarse to show individual effects, the tuberculosis marker relies on self-report, and the radiograph categories bundle findings as different as scars, nodules, pleural thickening and cardiomegaly [@pinsky2006abnormalities; @eisenberg2010low], so exposure effects could be diluted. Even so, a pattern this large and persistent that tracks none of the major causes of chest radiograph abnormalities is unlikely to be explained by disease alone.",
 "### Reading and reporting practice",
 "A plausible further contributor is how screening radiographs are read and reported. Readers of screening radiographs differ widely in how often they report nonspecific findings [@singh2012reader], and in Korea's lung cancer screening programme positive rates varied several-fold between radiologists and institutions [@hwang2021variability]. General health screening is delivered by many facilities of different sizes, and radiographs in high-volume, low-prevalence settings are read under heavy workload [@yoo2022artificial; @kim2023multicentre]. The large improvement in fit when province-by-year effects were added, the share of variance lying between provinces and the drift in district rankings over the decade are compatible with regional screening arrangements that change over time. The direct markers available here, clinic density and the suspected tuberculosis share from the same reading, were not associated, so reading practice was not measured directly and remains a hypothesis. Facility-level data on readers, volumes and the use of computer-aided or AI reading [@kim2021performance; @li2008lung] would be needed to test it.",
 "### Deprivation and physical activity",
 "Fewer flags with more basic livelihood security receipt was against the expected direction, because neighbourhood deprivation is associated with emphysema and lung function decline [@thatipelli2022neighborhood]. The association arose within districts over time, strengthened in later years and was absent between districts, so it describes years in which receipt rose rather than poorer districts; changes in eligibility for the benefit and in who attends screening [@shin2018association; @froom1999healthy] are possible time-varying explanations, and the credible negative-control exposure shows that residual confounding is present. More flags with more physical activity and sports facilities contradicted evidence that activity slows lung function decline [@garciaaymerich2007regular]; these associations disappeared when space–time interactions were modelled and were absent between districts, so they are not interpreted as effects.",
 "### Implications",
 "For radiology practice, the findings suggest that the other chest disease flag in national screening statistics should not be read as a measure of regional chest disease burden without first examining how it is generated. Routine audit of flag rates by screening facility, standardised for examinee sex and age, could identify outlying reading thresholds, and the published district series offers a baseline against which changes such as AI-assisted triage could be evaluated. Linking flags to follow-up imaging and diagnoses would show whether high-flag districts detect more disease or generate more false-positive findings.",
 "### Strengths and limitations",
 "The study covered every district with complete statistics for 14 years, standardised expected numbers for sex and age within the screened population and tested the associations in many sensitivity analyses. The flag has no published definition of findings, no information on the reader or facility and no link to follow-up, so its accuracy cannot be assessed. Counts are examinees in each year, not unique people, and the examinee age structure was estimated from residents and national uptake. The associations are ecological and cannot be transferred to individuals [@greenland2001ecologic]. Air pollution measurements and occupational histories were not available, and coal-fired power plants and industrial land are crude markers; tuberculosis history relied on the screening questionnaire. The dataset is a fixed analytic copy of the national statistics that is still being audited against the full set of source tables, and conclusions resting on specific cells should be rechecked when the audit is complete. The credible negative-control exposure and small E-values show that residual confounding could explain the weaker associations.",
 "### Conclusion",
 "The share of screening chest radiographs flagged as other chest disease in Korea varies widely and persistently between districts after sex and age are taken into account, without following tuberculosis history, smoking, industrial exposure or coal power. Before this flag is used to target follow-up or compare areas, reading and reporting practices across screening facilities should be audited.",
]

# 문장 주장 대조(결과표와 어긋나면 빌드 중단)
assert N["n_cred_hyp"] == 4 and N["n_robust"] == 3 and N["waic_main"] < N["waic_forced"] and N["waic_nb"] < N["waic_pois"]
assert not any(M[v]["cred"] for v in NULL_EXPO + NULL_OTHER)
assert M[BL]["cred"] and M[BL]["IRR"] < 1 and M[PA]["cred"] and M[PA]["IRR"] > 1 and M[FAC]["cred"] and M[FAC]["IRR"] > 1 and M["tertiary_educated_share"]["cred"] and M["tertiary_educated_share"]["IRR"] < 1
assert N["mv"]["tertiary_educated_share"]["robust"] is False or not N["mv"]["tertiary_educated_share"]["robust"]
assert N["negctl"]["fires_per_10000"]["cred"] and not N["negctl"]["hit_and_run_rate"]["cred"] and not N["negctl"]["waste_recycling_rate"]["cred"]
assert all(dW(a) < 0 for a in KH) and all(S43(a, BL)[3] for a in KH)
assert S43("KH_typeI", PA)[3] and S43("KH_typeI", FAC)[3] and not S43("KH_typeII", PA)[3] and not S43("KH_typeIV", PA)[3] and not S43("KH_typeII", FAC)[3] and not S43("KH_typeIV", FAC)[3]
assert all(S43(a, "current_smoking_rate")[3] and S43(a, "current_smoking_rate")[0] < 1 for a in ("KH_typeII", "KH_typeIII", "KH_typeIV"))
assert not N["bw"][BL + "__between"][3] and N["bw"][BL + "__within"][3] and not N["bw"][PA + "__between"][3] and not N["bw"][FAC + "__between"][3]
assert not WI(BL, "W1_2011-15")[3] and WI(BL, "W2_2016-19")[3] and WI(BL, "W3_2020-24")[3]
assert N["epop"][BL][3] and not any(NCO(o, v)[3] for o in ("RESP", "GCA") for v in (BL, PA))
assert not PH("tb_suspect", "ext__tb_suspect_share")[3] and not PH("detached", "detached_house_households")[3] and not PH("im_spec", "im_specialists_per_100k")[3] and PH("all3", BL)[3]
assert N["s41_waic"]["C4_sido_year_iid"] < N["waic_main"] - 100 and N["coal_mines_med"] < N["coal_others_med"] and N["rr_top"][0][0] == "강원도태백시"
assert sum(1 for k, v in N["coal_mines"].items() if v["class"] == "coldspot") == 3 and D["sir_max"] / D["sir_min"] > 2 and D["sir_p90"] / D["sir_p10"] > 1.8
